// One-bit thermostat controller. Implemented as a combinational function,
// the output signals (heater, aircon, fan) directly depend on the input
// signals (mode, too_cold, too_hot, fan_on) without any registers.
module TopModule(
    input mode,
    input too_cold,
    input too_hot,
    input fan_on,
    output reg heater,
    output reg aircon,
    output reg fan
);
    always @(*) begin
        heater = (mode & too_cold) | fan_on;
        aircon = (!mode & too_hot) | fan_on;
        fan = (heater | aircon) | fan_on;
    end
endmodule

