// combinational circuit, i.e. no registers. This means that the
// circuit is fully synchronous: it reacts to the clock pulse (it does
// one thing per clock cycle) and can therefore be pipelined (one stage
// per register, back-to-back).
module TopModule(
    input mode,
    input too_cold,
    input too_hot,
    input fan_on,
    output reg heater,
    output reg aircon,
    output reg fan
);
    always @(*) begin
        heater = (mode & too_cold) | fan_on;
        aircon = ((~mode) & too_hot) | fan_on;
        fan = heater | aircon | fan_on;
    end
endmodule

